{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    # Validate required fields in every node
    for node in nodes:
        for field in ["id", "parent", "symbol", "depth", "removable"]:
            if field not in node:
                raise ValueError(f"Missing required field '{field}' in node {node.get('id', '?')}")

    # Build lookup and children map
    node_map = {n["id"]: n for n in nodes}
    children = {n["id"]: [] for n in nodes}

    for n in nodes:
        if n["parent"] is not None:
            if n["parent"] not in node_map:
                raise ValueError(f"Parent '{n['parent']}' not found for node '{n['id']}'")
            children[n["parent"]].append(n["id"])

    # Validate all required symbols are present in the initial tree
    initial_symbols = {n["symbol"] for n in nodes}
    missing = required_symbols - initial_symbols
    if missing:
        raise ValueError(f"Required symbols not present in tree: {missing}")

    # Track retained nodes
    retained = set(node_map.keys())
    removed_order = []

    # Process deeper nodes first; tie-break by node ID (lexicographic)
    candidates = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    for node in candidates:
        nid = node["id"]
        if not node["removable"]:
            continue

        # Skip if any child is still retained
        if any(c in retained for c in children[nid]):
            continue

        # Tentatively remove and check required-symbol coverage
        retained.discard(nid)
        symbols_present = {node_map[rid]["symbol"] for rid in retained}

        if required_symbols.issubset(symbols_present):
            removed_order.append(nid)
        else:
            # Removal would lose a required symbol; restore
            retained.add(nid)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": sorted(retained)
    }"}
